// 1. Read the lead from the webhook (accepts "Lead Name" style or snake_case keys)
const body = $('Inbound Lead Webhook').first()?.json?.body ?? {};
const leadName = body['Lead Name'] ?? body.lead_name ?? body.name ?? 'Inbound Lead';
const email = body['Email'] ?? body.email ?? '';
const website = body['Company Website URL'] ?? body.company_website ?? body.website ?? '';
const challenge = body['Stated Challenge'] ?? body.stated_challenge ?? body.challenge ?? '';

// 2. Strip scripts, styles and tags from the scraped page, keep ~5,000 characters
let text = String($json.data ?? $json.html ?? '');
text = text
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 5000);

return {
  json: {
    lead_name: leadName,
    email: email,
    company_website: website,
    stated_challenge: challenge,
    scraped_text: text || 'Website content could not be retrieved.'
  }
};

// 1. Find the model's JSON answer anywhere in the model node's output
function findAiText(obj) {
  if (!obj) return null;
  if (typeof obj === 'string' && obj.includes('fit_score')) return obj;
  if (typeof obj === 'object') {
    for (const val of Object.values(obj)) {
      const found = findAiText(val);
      if (found) return found;
    }
  }
  return null;
}

const rawText = findAiText($json) ?? findAiText($('Message a model').first()?.json) ?? '';

let ai = null;
try {
  ai = JSON.parse(rawText.replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) {
  ai = null;
}
const ok = ai !== null && typeof ai === 'object';

// 2. Lead details come from the normalised Extract node (one lead per webhook call)
const lead = $('Extract Text From HTML').first().json;

// 3. If the AI answer could not be parsed, say so instead of filling in fake values
const score = ok ? Math.min(10, Math.max(0, Math.round(Number(ai.fit_score) || 0))) : 0;

return {
  json: {
    lead_name: lead.lead_name,
    email: lead.email,
    company_website: lead.company_website,
    stated_challenge: lead.stated_challenge,
    ai_parse_ok: ok,
    company: (ok && ai.company) || lead.company_website || 'Unknown',
    business_model: ok ? (ai.business_model || '') : '',
    fit_score: score,
    detected_pain_points: ok ? (ai.detected_pain_points || '') : '',
    sales_icebreaker: ok ? (ai.sales_icebreaker || '') : '',
    recommended_action: ok ? (ai.recommended_action || '') : 'Review manually: AI output could not be parsed'
  }
};

